{#- dacs-font: one font on every server — Liberation Sans (Arial's letter widths) shipped in the app
    (public/fonts), so a print measures and looks the same on local and live (docs/print-formats.md › Font) -#}
{%- set dacs_base = frappe.utils.get_url() -%}
<style>
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Regular.ttf') format('truetype'); font-weight: normal; font-style: normal; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Bold.ttf') format('truetype'); font-weight: bold; font-style: normal; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Italic.ttf') format('truetype'); font-weight: normal; font-style: italic; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-BoldItalic.ttf') format('truetype'); font-weight: bold; font-style: italic; }
body, body * { font-family: Arial !important; }
</style>
{#- Receipt Voucher (money from a customer) / Payment Voucher (money to a supplier / jobber) /
    Internal Transfer — one Payment Entry, however many invoices it settles: the invoices with
    their date, total and the amount set off, deductions (TDS, bank charges, write-off), what is
    left on account as an advance, amount in words, remarks, signatures. -#}
{%- set receive = doc.payment_type == "Receive" -%}
{%- set transfer = doc.payment_type == "Internal Transfer" -%}
{%- set title = "CONTRA VOUCHER" if transfer else ("RECEIPT VOUCHER" if receive else "PAYMENT VOUCHER") -%}
{%- set amount = (doc.received_amount if receive else doc.paid_amount) or 0 -%}
{%- macro acc(a) -%}{{ (a or "").rsplit(" - ", 1)[0] }}{%- endmacro -%}
{%- set words = frappe.utils.money_in_words(amount | float, "INR") | replace("INR ", "") | replace(" only.", "") | replace(" Only.", "") -%}
{%- set party_gstin = doc.billing_address_gstin or (frappe.db.get_value(doc.party_type, doc.party, "gstin") if doc.party_type in ("Customer", "Supplier") and doc.party else "") -%}
{%- set party_addr = frappe.db.get_value("Address", doc.customer_address, "address_line1") if doc.get("customer_address") else "" -%}
{%- set remarks = (doc.remarks or "") | trim if doc.custom_remarks else "" -%}
{%- set bank = doc.paid_to if receive else doc.paid_from -%}
{%- set chip = "DRAFT" if doc.docstatus == 0 else ("CANCELLED" if doc.docstatus == 2 else ("RECEIVED" if receive else ("PAID" if not transfer else "TRANSFERRED"))) -%}
{#- the letter head is the PDF page header, so it prints on every page (docs/print-formats.md › Page header) -#}
<div id="header-html" class="hidden-pdf">{% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}</div>
<div id="footer-html" class="visible-pdf"><p class="text-center small page-number visible-pdf" style="font-size:7.5pt;">Page <span class="page"></span> of <span class="topage"></span></p></div>
<style>
  /* page margins: the page header / footer set them (docs/print-formats.md › Page header) */
  .print-format > .page-break:last-child { page-break-after: auto; }
  /* terms written in the editor carry its "height: 100%" and scroll bars: inside the page box they stretched to the
     page and showed scroll arrows — the text keeps its own height */
  .print-format .ql-editor { height: auto !important; overflow: visible !important; padding: 0 !important; }
  .print-format .ql-editor p { margin: 0 !important; }
  /* letter head: tighter gaps (the Letter Head record is shared); the PDF page header's own 5mm bottom padding
     is the gap under the heading; a format with its own header (no letter head) starts at the header's top */
  .print-format .letter-head > div, .print-format .rn-letterhead > div, .print-format .pr-letterhead > div { margin-bottom: 1px !important; }
  .print-format .letter-head > div > div[style*="border-bottom"], .print-format .rn-letterhead > div > div[style*="border-bottom"],
  .print-format .pr-letterhead > div > div[style*="border-bottom"] { margin-top: 2px !important; }
  html body { padding-bottom: 1mm !important; }
  .pr { font-family: Arial, sans-serif; color: #000; font-size: 8.5pt; }
  .pr-letterhead { width: 100%; margin-bottom: 2px; }
  .pr-head { position: relative; text-align: center; margin: 2px 0 6px; }
  .pr-title { font-size: 12pt; font-weight: bold; letter-spacing: 1px; }
  .pr-sub { font-size: 8.5pt; line-height: 1.4; }
  .pr-chip { position: absolute; top: 0; right: 0; border: 2px solid #000; padding: 4px 10px; font-weight: bold; font-size: 10px; }
  .pr-box { width: 100%; border-collapse: collapse; border: 1.2px solid #000; table-layout: fixed; }
  .pr-box > tbody > tr > td { vertical-align: top; padding: 5px 6px; }
  .pr-l { border-right: 1.2px solid #000; width: 55%; }
  .pr-party { font-weight: bold; font-size: 10.5pt; text-transform: uppercase; }
  .pr-grid { width: 100%; border-collapse: collapse; }
  .pr-grid td { padding: 1.5px 0; vertical-align: top; }
  .pr-grid .k { width: 40%; font-weight: bold; white-space: nowrap; }
  .pr-amount { margin-top: 6px; border: 1.2px solid #000; background: #f2f2f2; padding: 6px 8px; font-size: 11pt; font-weight: bold; }
  .pr-amount small { font-size: 8.5pt; font-weight: normal; }
  .pr-h { font-weight: bold; margin: 8px 0 2px; font-size: 9pt; }
  .pr-t { width: 100%; border-collapse: collapse; }
  .pr-t th { border: 1px solid #000; background: #f2f2f2; padding: 3px 4px; text-align: left; }
  .pr-t td { border: 1px solid #000; padding: 3px 4px; vertical-align: top; }
  .pr-t .r { text-align: right; white-space: nowrap; }
  .pr-t tr.tot td { font-weight: bold; background: #fafafa; }
  .pr-words { border: 1px solid #000; padding: 4px 6px; margin-top: 8px; background: #fafafa; }
  .pr-foot { width: 100%; border-collapse: collapse; border: 1px solid #000; border-top: none; table-layout: fixed; }
  .pr-foot td { vertical-align: top; padding: 5px 6px; }
  .pr-sign { text-align: center; }
  .pr-sign span { display: inline-block; border-top: 1px solid #000; width: 85%; padding-top: 2px; font-weight: bold; }
</style>
<div class="pr">

  <div class="pr-head">
    <div class="pr-title">{{ title }}</div>
    <div class="pr-sub">No: <strong>{{ doc.name }}</strong> | Date: <strong>{{ frappe.utils.formatdate(doc.posting_date, "dd-MMM-yyyy") }}</strong></div>
    <div class="pr-chip">{{ chip }}</div>
  </div>

  <table class="pr-box"><tr>
    <td class="pr-l">
      {% if transfer %}
        <div class="pr-party">Between our own accounts</div>
        <table class="pr-grid" style="margin-top:3px;">
          <tr><td class="k">From</td><td>: {{ acc(doc.paid_from) }}</td></tr>
          <tr><td class="k">To</td><td>: {{ acc(doc.paid_to) }}</td></tr>
        </table>
      {% else %}
        <div style="font-size:7.5pt;">{{ "Received with thanks from" if receive else "Paid to" }}</div>
        <div class="pr-party">M/s. {{ doc.party_name or doc.party }}</div>
        <div style="font-size:7.5pt;color:#333;">{{ doc.party_type }}: {{ doc.party }}</div>
        {% if party_addr %}<div style="font-size:8pt;">{{ party_addr }}</div>{% endif %}
        {% if party_gstin %}<div style="margin-top:2px;"><strong>G.S.T. : </strong>{{ party_gstin }}</div>{% endif %}
      {% endif %}
    </td>
    <td>
      <table class="pr-grid">
        <tr><td class="k">Mode of Payment</td><td>: {{ doc.mode_of_payment or "—" }}</td></tr>
        {% if doc.reference_no %}<tr><td class="k">Cheque / Ref. No.</td><td>: {{ doc.reference_no }}</td></tr>{% endif %}
        {% if doc.reference_date %}<tr><td class="k">Cheque / Ref. Date</td><td>: {{ frappe.utils.formatdate(doc.reference_date) }}</td></tr>{% endif %}
        {% if not transfer %}<tr><td class="k">{{ "Deposited to" if receive else "Paid from" }}</td><td>: {{ acc(bank) }}</td></tr>{% endif %}
        {% if doc.bank %}<tr><td class="k">Party's Bank</td><td>: {{ doc.bank }}</td></tr>{% endif %}
      </table>
    </td>
  </tr></table>

  {% if doc.get("custom_bulk_payment") %}{%- set bp = frappe.db.get_value("Bulk Payment", doc.custom_bulk_payment, ["total_amount", "party_count"], as_dict=1) -%}
  <div style="margin-top:6px;font-size:8pt;border:1px dashed #000;padding:3px 6px;">Part of Bulk Payment <strong>{{ doc.custom_bulk_payment }}</strong>{% if bp %} — ₹ {{ frappe.utils.fmt_money(bp.total_amount) }} for {{ bp.party_count }} parties; this receipt covers this party's share{% endif %}.</div>{% endif %}
  <div class="pr-amount">{{ "Amount Received" if receive else ("Amount Transferred" if transfer else "Amount Paid") }}: ₹ {{ frappe.utils.fmt_money(amount | float) }}
    <small>&nbsp;({{ doc.mode_of_payment or "" }}{% if doc.reference_no %}, Ref. {{ doc.reference_no }}{% endif %})</small></div>

  {% if doc.references %}
  <div class="pr-h">{{ "Invoices settled by this receipt" if receive else "Bills settled by this payment" }}</div>
  <table class="pr-t">
    <thead><tr><th style="width:6%;">#</th><th>{{ "Invoice" if receive else "Bill" }} No.</th>{% if not receive %}<th>Supplier Bill No.</th>{% endif %}
      <th style="width:16%;">Date</th><th class="r" style="width:20%;">{{ "Invoice" if receive else "Bill" }} Total</th><th class="r" style="width:20%;">Amount set off</th></tr></thead>
    <tbody>
    {% for r in doc.references %}
      {%- set rdate = frappe.db.get_value(r.reference_doctype, r.reference_name, "posting_date") if r.reference_doctype in ("Sales Invoice", "Purchase Invoice", "Journal Entry") else (frappe.db.get_value(r.reference_doctype, r.reference_name, "transaction_date") if r.reference_doctype in ("Sales Order", "Purchase Order") else None) -%}
      <tr>
        <td>{{ loop.index }}</td>
        <td><strong>{{ r.reference_name }}</strong>{% if r.reference_doctype not in ("Sales Invoice", "Purchase Invoice") %}<div style="font-size:7pt;">{{ r.reference_doctype }}</div>{% endif %}</td>
        {% if not receive %}<td>{{ r.bill_no or "" }}</td>{% endif %}
        <td>{{ frappe.utils.formatdate(rdate) if rdate else "" }}</td>
        <td class="r">{{ frappe.utils.fmt_money(r.total_amount or 0) }}</td>
        <td class="r"><strong>{{ frappe.utils.fmt_money(r.allocated_amount or 0) }}</strong></td>
      </tr>
    {% endfor %}
      <tr class="tot"><td colspan="{{ 5 if not receive else 4 }}" class="r">Total set off</td><td class="r">₹ {{ frappe.utils.fmt_money(doc.total_allocated_amount or 0) }}</td></tr>
    </tbody>
  </table>
  {% endif %}

  {#- How the bank amount and the deductions make up what was set off. Deductions are debits:
      on a receipt they add to what the customer settled (TDS they deducted, bank charges);
      on a voucher a negative row (TDS we deducted, write-off) adds, a positive one (bank charges) is extra paid. -#}
  {% if not transfer and (doc.deductions or (doc.unallocated_amount or 0) > 0.005) %}
  <table class="pr-t" style="margin-top:8px;width:60%;margin-left:40%;">
    <tr><td>{{ "Received through " if receive else "Paid through " }}{{ doc.mode_of_payment or "bank" }}</td><td class="r">{{ frappe.utils.fmt_money(amount | float) }}</td></tr>
    {% for d in doc.deductions %}
      {%- set eff = (d.amount or 0) | float if receive else -((d.amount or 0) | float) -%}
      <tr><td>{{ "+" if eff >= 0 else "−" }} {{ acc(d.account) }}{% if d.description %} <span style="font-size:7pt;">({{ d.description }})</span>{% endif %}</td>
          <td class="r">{{ frappe.utils.fmt_money(eff | abs) }}</td></tr>
    {% endfor %}
    <tr class="tot"><td>Set off against {{ "invoices" if receive else "bills" }}</td><td class="r">{{ frappe.utils.fmt_money(doc.total_allocated_amount or 0) }}</td></tr>
    {% if (doc.unallocated_amount or 0) > 0.005 %}<tr class="tot"><td>Advance / on account (to adjust later)</td><td class="r">{{ frappe.utils.fmt_money(doc.unallocated_amount) }}</td></tr>{% endif %}
  </table>
  {% endif %}

  <div class="pr-words"><strong>Amount in Words:</strong> <i><strong>Rupees {{ words }} Only</strong></i></div>
  <table class="pr-foot"><tr>
    <td style="width:{{ '40%' if not transfer else '70%' }};border-right:1px solid #000;">
      <div style="font-weight:bold;text-decoration:underline;margin-bottom:2px;">Remarks</div>
      <div style="white-space:pre-wrap;">{{ remarks or "—" }}</div>
      {% if receive and doc.mode_of_payment and "cheque" in (doc.mode_of_payment | lower) %}<div style="font-size:7pt;margin-top:4px;">Subject to realisation of the cheque.</div>{% endif %}
    </td>
    {% if not transfer %}
    <td class="pr-sign" style="width:30%;border-right:1px solid #000;"><br><br><br><br><span>{{ "Customer's Signature" if receive else "Receiver's Signature" }}</span></td>
    {% endif %}
    <td class="pr-sign" style="width:30%;"><div style="font-weight:bold;">For {{ doc.company }}</div><br><br><br><span>Authorised Signatory</span></td>
  </tr></table>
</div>
